    public static ReadOnlySpan<XtNodeDescriptor> Nodes => NodeData;
    public static ReadOnlySpan<XtFieldDescriptor> Fields => FieldData;

    public static XtNodeDescriptor GetNode(XtNodeType type)
    {
        foreach (var node in Nodes)
        {
            if (node.Type == type)
                return node;
        }

        return default;
    }
}

internal readonly record struct XtNodeDescriptor(
    XtNodeType Type,
    string Name,
    string Description,
    bool Transmit,
    XtFieldCount FieldCount,
    bool Variable,
    XtFieldIndex FieldOffset,
    XtFieldCount ParsedFieldCount);

internal readonly record struct XtFieldDescriptor(
    XtNodeType OwnerType,
    string Name,
    char Type,
    bool Transmit,
    XtNodeClass NodeClass,
    XtFieldElementCount ElementCount);
